mapper.select:
SELECT  FROM t_beneficiary_account
WHERE owner_type = #{ownerType} AND owner_id = #{ownerId}
AND status = #{status}
AND currency = #{currency}
ORDER BY currency, create_time, id

SELECT account_code FROM t_beneficiary_account
WHERE owner_type = #{ownerType} AND owner_id = #{ownerId}
ORDER BY CHAR_LENGTH(account_code) DESC, account_code DESC LIMIT 1

SELECT  FROM t_beneficiary_account
WHERE bank_account_token = #{bankAccountToken} AND active_key = 0 AND NOT (owner_type = #{ownerType} AND owner_id = #{ownerId})
ORDER BY create_time, id LIMIT #{limit}

SELECT FROM t_beneficiary_account
ORDER BY decision_time DESC, id DESC ORDER BY create_time, id
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE t_beneficiary_account
SET review_maker_id = #{makerId}, review_maker_decision = #{decision}, review_maker_note = #{makerNote}, reason_code = #{reasonCode}, reason_note = #{reasonNote}, version = version + 1, update_time = #{now}
WHERE id = #{record.id} AND version = #{record.version} AND status = 'PENDING_REVIEW' AND review_maker_id IS NULL

UPDATE t_beneficiary_account
SET status = #{status}, checker_id = #{checkerId}, checker_decision = #{decision}, decision_time = #{now}, reason_code = #{reasonCode}, reason_note = #{reasonNote}, cooling_until = #{coolingUntil}, version = version + 1, update_time = #{now}
WHERE id = #{record.id} AND version = #{record.version} AND status = 'PENDING_REVIEW' AND review_maker_id IS NOT NULL

UPDATE t_beneficiary_account
SET is_default = #{isDefault}, version = version + 1, update_time = #{now}
WHERE id = #{record.id} AND version = #{record.version} AND status = #{record.status}

UPDATE t_beneficiary_account
SET status = #{status}, reason_code = #{reasonCode}, reason_note = NULL, is_default = 0, version = version + 1, update_time = #{now}
WHERE id = #{record.id} AND version = #{record.version} AND status = #{record.status}

UPDATE t_beneficiary_account
SET status = 'PENDING_REVIEW', review_maker_id = NULL, review_maker_decision = NULL, review_maker_note = NULL, checker_id = NULL, checker_decision = NULL, decision_time = NULL, reason_code = NULL, reason_note = NULL, cooling_until = NULL, version = version + 1, update_time = #{now}
WHERE id = #{record.id} AND version = #{record.version} AND status = 'SUSPENDED'
